def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []

    def parse_amount(token):
        if not token or any(ch < "0" or ch > "9" for ch in token):
            return None
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        if any(not part for part in parts):
            rejected.append(index)
            continue

        verb = parts[0]
        success = False

        if verb == "undo" and len(parts) == 1:
            if history:
                for name, previous in history.pop():
                    if previous is None:
                        del accounts[name]
                    else:
                        accounts[name] = previous
                success = True

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            name = parts[1]
            desired = verb == "freeze"
            if name in accounts and accounts[name][1] != desired:
                history.append([(name, accounts[name])])
                accounts[name] = (accounts[name][0], desired)
                success = True

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            name = parts[1]
            amount = parse_amount(parts[2])
            if amount is not None:
                if verb == "open" and name not in accounts:
                    history.append([(name, None)])
                    accounts[name] = (amount, False)
                    success = True
                elif verb == "deposit" and amount > 0 and name in accounts:
                    balance, frozen = accounts[name]
                    history.append([(name, accounts[name])])
                    accounts[name] = (balance + amount, frozen)
                    success = True
                elif verb == "withdraw" and amount > 0 and name in accounts:
                    balance, frozen = accounts[name]
                    if not frozen and balance >= amount:
                        history.append([(name, accounts[name])])
                        accounts[name] = (balance - amount, frozen)
                        success = True

        elif verb == "transfer" and len(parts) == 4:
            source, destination = parts[1], parts[2]
            amount = parse_amount(parts[3])
            if (
                amount is not None
                and amount > 0
                and source != destination
                and source in accounts
                and destination in accounts
            ):
                source_balance, source_frozen = accounts[source]
                destination_balance, destination_frozen = accounts[destination]
                if not source_frozen and source_balance >= amount:
                    history.append([
                        (source, accounts[source]),
                        (destination, accounts[destination]),
                    ])
                    accounts[source] = (source_balance - amount, source_frozen)
                    accounts[destination] = (
                        destination_balance + amount,
                        destination_frozen,
                    )
                    success = True

        if not success:
            rejected.append(index)

    return {name: state[0] for name, state in accounts.items()}, rejected
